require_once __DIR__ . '/_components.php';require_once __DIR__ . '/../app/application.php';requirePermission('contracts.manage');$q=dbFetchOne('SELECT r.*,c.first_name,c.last_name,c.email,v.registration_number,v.brand,v.model,a.name agency_name FROM reservations r JOIN customers c ON c.id=r.customer_id LEFT JOIN vehicles v ON v.id=r.vehicle_id JOIN agencies a ON a.id=r.agency_id WHERE r.id=:id AND r.status=\'quote\'',['id'=>(int)($_GET['id']??0)]);if(!$q){printNotFound(t('validation.quote_not_found'));}requireAgencyAccess($q['agency_id']);?><!doctype html><html><head><meta charset="utf-8"><title><?=e($q['reference'])?></title><link rel="icon" href="assets/img/aurevo-mark.png"><link rel="stylesheet" href="assets/app.css"><style>@media print{button{display:none}}</style></head><body><main class="page"><button class="btn secondary" onclick="print()">Print / Save PDF</button><h1>Rental quote <?=e($q['reference'])?></h1><p><?=e($q['agency_name'])?> · Issued <?=e($q['created_at'])?></p><div class="grid"><section class="card"><h2>Customer</h2><p><?=e($q['first_name'].' '.$q['last_name'])?></p><p><?=e($q['email'])?></p></section><section class="card"><h2>Vehicle</h2><p><?=e($q['brand'].' '.$q['model'])?></p><p><?=e($q['registration_number'])?></p></section></div><section class="card"><p><?=e($q['pickup_at'])?> — <?=e($q['return_at'])?></p><p><?=e($q['rental_days'])?> day(s) × <?=money($q['daily_price'],$q['currency'])?></p><h2>Total: <?=money($q['total_amount'],$q['currency'])?></h2><p>This quote is subject to vehicle availability until converted and confirmed.</p></section></main></body></html>

